import {enterpriseModel} from './enterprise-models.js';
export function enterpriseState(n){const e=n.net.enterprise??={policies:[],routes:[],logs:[],logTarget:'',collector:false,incidents:[],saved:false};e.addresses??={};e.interfaces??=[];return e;}
const ipOK=s=>/^\d{1,3}(\.\d{1,3}){3}$/.test(s||'')&&s.split('.').every(x=>+x<256);
const words=s=>s.match(/"[^"]*"|\S+/g)?.map(v=>v.replace(/^"|"$/g,''))||[];
export function applyEnterprise(n,a){const e=enterpriseState(n),role=enterpriseModel(n).role;
 if(a.op==='interface-address'){const p=n.ports[a.index];if(!p||!ipOK(a.ip)||!Number.isInteger(a.prefix)||a.prefix<1||a.prefix>30)return 'Use a valid interface and IPv4/prefix';p.cfg.ip=a.ip;p.cfg.prefix=a.prefix;}
 else if(a.op==='subinterface'){const v=a.value,parent=n.ports.find(p=>p.name===v.parent);if(role!=='firewall'||!parent||!Number.isInteger(v.vlanid)||v.vlanid<1||v.vlanid>4094||!ipOK(v.ip)||!Number.isInteger(v.prefix)||v.prefix<1||v.prefix>30)return 'Set interface, vlanid and a valid IP/mask';e.interfaces??=[];e.interfaces=e.interfaces.filter(x=>x.name!==v.name).concat({...v});{n.net.vlans[v.vlanid]=v.name;parent.cfg.mode='trunk';parent.cfg.allowed=[...new Set([...parent.cfg.allowed,v.vlanid])];}}
 else if(a.op==='policy'){if(role!=='firewall')return 'Firewall policy is only available on firewalls';const p=a.value;if(!Number.isInteger(p.id)||p.id<1||!['accept','deny'].includes(p.action)||![...n.ports,...e.interfaces].some(x=>x.name===p.srcintf)||![...n.ports,...e.interfaces].some(x=>x.name===p.dstintf))return 'Select valid ingress/egress ports and accept or deny';if([p.srcaddr,p.dstaddr].some(x=>x&&x!=='all'&&!e.addresses[x]))return 'Create the address object first';if(p.service&&!['ALL','HTTP','HTTPS','SSH','DNS','SMB','NFS','ICMP'].includes(p.service))return 'Unsupported service';const value={srcaddr:p.srcaddr||'all',dstaddr:p.dstaddr||'all',service:p.service||'ALL',logtraffic:p.logtraffic||'all',schedule:'always',hits:0,bytes:0,id:p.id,name:String(p.name||'Policy '+p.id).slice(0,48),srcintf:p.srcintf,dstintf:p.dstintf,action:p.action,nat:!!p.nat,enabled:p.enabled!==false};const i=e.policies.findIndex(x=>x.id===p.id);if(i>=0)e.policies[i]=value;else e.policies.push(value);}
 else if(a.op==='address'){const v=a.value;if(!/^[\w.-]{1,63}$/.test(v.name||'')||!ipOK(v.subnet?.split('/')[0])||!/^\d+$/.test(v.subnet?.split('/')[1]||'')||+v.subnet.split('/')[1]>32)return 'Enter address name and IPv4/prefix';e.addresses[v.name]={name:v.name,subnet:v.subnet};}
 else if(a.op==='move-policy'){const i=e.policies.findIndex(x=>x.id===+a.value.id),j=i+(a.value.direction==='up'?-1:1);if(i<0||j<0||j>=e.policies.length)return 'Policy is already at the end';[e.policies[i],e.policies[j]]=[e.policies[j],e.policies[i]];}
 else if(a.op==='delete-policy'){e.policies=e.policies.filter(x=>x.id!==+a.value.id);}
 else if(a.op==='logging'){e.logTarget=String(a.target||'').slice(0,80);}
 else if(a.op==='collector'){if(!['logs','siem'].includes(role))return 'Select a FortiAnalyzer or SIEM host';e.collector=!!a.enabled;}
 else if(a.op==='ack'){const incident=e.incidents.find(i=>i.id===a.id);if(!incident)return 'Incident not found';incident.status='Acknowledged';}
 else if(a.op==='route'){const v=a.value;if(!Number.isInteger(v.id)||v.id<1||!ipOK(v.dst?.split('/')[0])||!/^\d+$/.test(v.dst?.split('/')[1]||'')||+v.dst.split('/')[1]>32||!ipOK(v.gateway)||!n.ports.some(p=>p.name===v.device))return 'Use destination/prefix, gateway and a valid interface';e.routes=e.routes.filter(x=>x.id!==v.id).concat({id:v.id,dst:v.dst,gateway:v.gateway,device:v.device});}
 else if(a.op==='save')e.saved=true;
 else return 'Unsupported enterprise setting';return 'Applied to '+n.id;
}
export function receiveEvent(source,text,nodes,reachable){const e=enterpriseState(source),record={at:Date.now(),source:source.id,message:String(text).slice(0,180)};e.logs.unshift(record);e.logs=e.logs.slice(0,200);const target=nodes.find(n=>n.id===e.logTarget||n.net?.ip===e.logTarget);if(!target||target===source||!enterpriseState(target).collector||!reachable(source,target,source.net.vlan))return;const t=enterpriseState(target);t.logs.unshift(record);t.logs=t.logs.slice(0,200);if(enterpriseModel(target).role==='siem'&&/DENY|shutdown|down/i.test(text)){const recent=t.logs.filter(x=>x.source===source.id&&Date.now()-x.at<60000&&/DENY|shutdown|down/i.test(x.message));if(recent.length>=3&&!t.incidents.some(i=>i.source===source.id&&i.status==='Open'))t.incidents.unshift({id:'INC-'+Date.now().toString(36),source:source.id,status:'Open',message:'Repeated deny/down events in 60 seconds'});t.incidents=t.incidents.slice(0,100);}}
export function policyTest(n,src,dst){const rule=enterpriseState(n).policies.find(p=>p.enabled&&p.srcintf===src&&p.dstintf===dst);return {allowed:rule?.action==='accept',rule:rule?.id||'implicit deny',nat:!!rule?.nat};}
export async function enterpriseCLI(input,session,change,probe){const n=session.node,c=n.net,e=enterpriseState(n),profile=enterpriseModel(n),text=input.trim(),lower=text.toLowerCase();let m;
 const update=(op,extra={})=>change({type:'enterprise',node:n.id,op,...extra});
 if(['write memory','copy running-config startup-config','execute cfg save'].includes(lower))return update('save');
 if(lower==='get system status')return `${profile.vendor} ${n.model}\n${profile.os} training profile\nHostname: ${c.hostname||n.id}\nManagement: ${c.ip}/${c.prefix}\nPolicies: ${e.policies.length}`;
 if(['show interface status','show interfaces status','get system interface physical'].includes(lower))return n.ports.map(p=>`${p.alias||p.name}  ${p.cfg.admin?'up':'administratively down'}  ${p.speed}G  ${p.link&&!p.link.unplugged?'connected':'no link'}`).join('\n');
 if(['show ip interface brief','get router info routing-table all'].includes(lower))return `Management ${c.ip}/${c.prefix} VLAN ${c.vlan}\n`+e.routes.map(r=>`${r.dst} via ${r.gateway} dev ${r.device}`).join('\n');
 if(lower==='show firewall policy')return e.policies.map(p=>`${p.id} ${p.name}: ${p.srcintf} → ${p.dstintf} ${p.action} NAT ${p.nat?'on':'off'}`).join('\n')||'No policies · implicit deny';
 if(lower==='show logs')return e.logs.map(l=>`${new Date(l.at).toISOString()} ${l.source}: ${l.message}`).join('\n')||'No events received';
 if(lower==='show incidents')return e.incidents.map(i=>`${i.id} ${i.status}: ${i.source} ${i.message}`).join('\n')||'No correlated incidents';
 if(m=/^test policy (\S+) (\S+)$/i.exec(text)){if(profile.role!=='firewall')return 'Policy test requires a firewall';return probe(n,m[1],m[2]);}
 if(m=/^logging host (\S+)$/i.exec(text))return update('logging',{target:m[1]});
 if(lower==='collector enable'||lower==='collector disable')return update('collector',{enabled:lower.endsWith('enable')});
 if(m=/^acknowledge (\S+)$/i.exec(text))return update('ack',{id:m[1]});
 if(lower==='show vlan brief')return Object.entries(c.vlans).map(([id,name])=>`${id} ${name}`).join('\n');
 if(lower==='feature ssh'&&profile.role==='switch')return change({type:'ssh',node:n.id,enabled:true});
 if(profile.vendor!=='Fortinet'||!['firewall','logs','siem'].includes(profile.role))return null;
 if(lower==='help')return 'config system interface → edit mgmt → set ip IP MASK → set allowaccess ping https ssh → next → end\nconfig system global → set hostname NAME → end\nconfig firewall policy → edit 1 → set srcintf port1 → set dstintf port2 → set action accept|deny → set nat enable|disable → next → end\nconfig router static → edit 1 → set dst NETWORK MASK → set gateway IP → set device port1 → next → end\nconfig log fortianalyzer setting → set server IP → end\nget system status | show firewall policy | test policy port1 port2\nshow logs | collector enable | show incidents | acknowledge INCIDENT-ID\nSupported training subset; policies match one ingress/egress pair.';
 if(m=/^config (system interface|system global|firewall policy|firewall address|router static|log fortianalyzer setting)$/i.exec(text)){session.forti=m[1].toLowerCase();session.config=true;session.draft=null;session.interfaceDraft=null;return `${c.hostname||n.id} (${session.forti}) #`;}
 if(!session.forti){if(/^(configure terminal|conf t|switchport |vlan |shutdown|no shutdown)/i.test(text))return 'Use FortiOS syntax: config system interface. Type help.';return null;}
 if(m=/^edit (.+)$/i.exec(text)){const key=words(m[1])[0];if(session.forti==='system interface'){const p=n.ports.find(p=>p.name.toLowerCase()===key.toLowerCase()||p.alias?.toLowerCase()===key.toLowerCase());if(!p){session.interface=null;session.interfaceDraft={name:key,parent:'',vlanid:null,ip:'',prefix:null};return 'New VLAN interface · set interface, vlanid and ip';}session.interfaceDraft=null;session.interface=n.ports.indexOf(p);}else if(session.forti==='firewall policy'){if(profile.role!=='firewall')return 'Policies are only available on FortiGate';session.draft={id:+key,srcintf:'',dstintf:'',action:'deny',nat:false,...e.policies.find(x=>x.id===+key)};}else if(session.forti==='firewall address')session.draft={name:key,...e.addresses[key]};else if(session.forti==='router static')session.draft={id:+key,dst:'0.0.0.0/0',gateway:'',device:''};return `${n.id} (${key}) #`;}
 if(lower==='next'||lower==='end'){let result='Context closed';if(session.interfaceDraft){result=await update('subinterface',{value:session.interfaceDraft});if(!result.startsWith('Applied'))return result;session.interfaceDraft=null;}if(session.draft){result=await update(session.forti==='firewall policy'?'policy':session.forti==='firewall address'?'address':'route',{value:session.draft});if(!result.startsWith('Applied'))return result;}session.draft=null;session.interface=null;if(lower==='end'){session.forti=null;session.config=false;}return result;}
 if(m=/^delete (\d+)$/i.exec(text)){if(session.forti==='firewall policy')return update('delete-policy',{value:{id:+m[1]}});return 'Delete is supported for firewall policies';}
 if(m=/^unset (srcaddr|dstaddr|service|nat)$/i.exec(text)){if(!session.draft)return 'Select a record with edit first';session.draft[m[1]]=m[1]==='nat'?false:m[1]==='service'?'ALL':'all';return 'Staged · next to apply';}
 if(m=/^set (\S+) (.+)$/i.exec(text)){const key=m[1].toLowerCase(),value=words(m[2])[0];if(session.interfaceDraft){const d=session.interfaceDraft;if(key==='interface')d.parent=value;else if(key==='vlanid')d.vlanid=+value;else if(key==='ip'){const [ip,mask]=words(m[2]);d.ip=ip.split('/')[0];d.prefix=ip.includes('/')?+ip.split('/')[1]:maskPrefix(mask);}else return 'Use set interface, set vlanid or set ip';return 'Staged VLAN interface · next to apply';}if(session.draft){if(session.forti==='firewall address'){if(key!=='subnet')return 'Use set subnet ADDRESS MASK';const [ip,mask]=words(m[2]);session.draft.subnet=ip.includes('/')?ip:ip+'/'+maskPrefix(mask);return 'Staged · next to apply';}if(['name','srcintf','dstintf','action','gateway','device'].includes(key))session.draft[key]=value;else if(key==='nat')session.draft.nat=value==='enable';else if(key==='status')session.draft.enabled=value==='enable';else if(key==='dst'){const [ip,mask]=words(m[2]);session.draft.dst=ip.includes('/')?ip:ip+'/'+maskPrefix(mask);}else if(['srcaddr','dstaddr','service','logtraffic'].includes(key))session.draft[key]=value;else if(key==='schedule'&&value!=='always')return 'Only the always schedule is currently supported';else return 'Unsupported policy field';return 'Staged · next to apply';}
 if(key==='hostname')return change({type:'settings',node:n.id,value:{hostname:value}});
 if(key==='server')return update('logging',{target:value});
 if(session.forti==='system interface'&&Number.isInteger(session.interface)){const p=n.ports[session.interface];if(['alias','role','allowaccess'].includes(key)){if(key==='allowaccess')await change({type:'ssh',node:n.id,enabled:words(m[2]).includes('ssh')});return change({type:'cli-state',node:n.id,op:'interface',index:session.interface,value:{[key]:key==='allowaccess'?words(m[2]):value}});}if(key==='mode'){if(!['static','dhcp'].includes(value))return 'Use static or dhcp';return change({type:'settings',node:n.id,value:{addressing:value}});}if(key==='status')return change({type:'port',node:n.id,index:session.interface,value:{admin:value==='up'}});if(key==='ip'){const [ip,mask]=words(m[2]);const address={ip:ip.split('/')[0],prefix:ip.includes('/')?+ip.split('/')[1]:maskPrefix(mask)};return p.name==='MGMT UPLINK'||p.alias==='mgmt'?change({type:'address',node:n.id,...address}):update('interface-address',{index:session.interface,...address});}if(key==='allowaccess')return change({type:'ssh',node:n.id,enabled:words(m[2]).includes('ssh')});}
 return 'Unsupported setting in this context. Type help.';}
 return 'Use set, next or end in this FortiOS context.';
}
function maskPrefix(mask){if(!ipOK(mask))return NaN;const bits=mask.split('.').map(x=>(+x).toString(2).padStart(8,'0')).join('');return /^1*0*$/.test(bits)?bits.indexOf('0')===-1?32:bits.indexOf('0'):NaN;}
